string-array.item:
INSERT INTO content (key, title, subtitle, text, footer) VALUES
(1, null, "Narrated by 'Umar bin Al-Khattab", "I heard Allah's Apostle saying, \"The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended. So whoever emigrated for worldly benefits or for a woman to marry, his emigration was for what he emigrated for.\""),
(6, \"Other\");
